// Pull the query out of the webhook payload.
const body = $input.first()?.json?.body || $input.first()?.json || {};
const query = (body.query || body.q || body.text || '').toString().trim();
if (!query) {
  return [{ json: { error: 'no query supplied', usage: 'POST { query: "..." }' } }];
}
return [{ json: { query } }];

// Merge Brave + Tavily results.
const brave = $('Brave search').first()?.json?.web?.results || [];
const tavily = $('Tavily search').first()?.json || {};
const tavilyAnswer = tavily.answer || '';
const tavilyResults = tavily.results || [];

const combined = [];
for (const r of brave.slice(0, 5)) combined.push({ title: r.title, url: r.url, snippet: r.description, source: 'brave' });
for (const r of tavilyResults.slice(0, 5)) combined.push({ title: r.title, url: r.url, snippet: r.content, source: 'tavily' });

// Dedupe by URL.
const seen = new Set();
const dedup = combined.filter(x => { if (seen.has(x.url)) return false; seen.add(x.url); return true; });

const summary = `Найдено ${dedup.length} источников. ${tavilyAnswer ? 'Краткий ответ: ' + tavilyAnswer : ''}`;
const sources = dedup.slice(0, 8).map((r, i) => `${i+1}. ${r.title} — ${r.url}`).join('\n');

return [{ json: { summary, sources, results: dedup.slice(0, 8), query: $('Parse query').first().json.query, ts: new Date().toISOString() } }];
